/**
 * Defaults for a conversation draft BEFORE schema validation, shared by every
 * agent write path that receives the project slug SEPARATELY from the body:
 * `convo create` (server/cli/convo.ts), MCP `convo_create`
 * (server/mcp/hubWriteTools.ts) and MCP `capture_gate`
 * (server/mcp/brainTools.ts).
 *
 * Chip 2026-09-25-fill-convo-project-from-the-create-slug: a body without
 * `project` failed the schema ("champ "project": expected object") even though
 * the slug was already the command's first positional argument, and agents
 * had to rebuild the JSON by hand each time. This fills what the call already
 * knows. `ConversationSchema` (src/types/conversation.ts) is NOT loosened: the
 * defaulted object is validated against it unchanged, right after.
 *
 * Filled only when absent (`null` counts as absent, like the `??=` it
 * replaces):
 *   - `schemaVersion: 1`, `status: 'pending'`, `createdAt`/`updatedAt: now`;
 *   - `project` from the positional slug (see `resolveDraftProject`); a
 *     partial `project` gets its missing fields; a `project.slug` that
 *     DIFFERS from the positional slug is refused — never silently rewritten;
 *   - per item: `status: 'pending'`, and `prompt` from `title` (the card
 *     heading is `prompt`; `title` is only its short TOC label, so a draft
 *     carrying just `title` loses nothing).
 *
 * `origin`/`createdBy` stay at each call site: they come from the runtime
 * origin resolver, whose trust rules differ per path.
 */
import { promises as fs } from 'node:fs';
import path from 'node:path';

import { dataDir } from '../config';
import { getConversation } from './conversationStore';
import { projectSiblingNames } from './chipStore';
import { disambiguateSlugCollisions, slugify } from './slug';

export interface DraftProject {
  slug: string;
  name: string;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/** Ceiling on file reads when looking for a name — the unparseable-file worst
 * case must not read a whole slug directory (315 files under `second-brain`),
 * same bounded-lookup idiom as `MAX_IDLE_LOOKUPS` (server/services/insights.ts). */
const MAX_NAME_LOOKUPS = 5;

/** Name the hub already shows for `slug`: the first readable conversation
 * filed under it, filenames in descending order (date-prefixed ids come
 * newest-first among themselves; other ids — `sb-…`, `req-…` — sort before
 * them, which is fine since every conversation of a slug carries the same
 * name in practice). One `readdir` and at most `MAX_NAME_LOOKUPS` reads —
 * never a parse of the whole slug. */
async function latestConversationName(slug: string): Promise<string | undefined> {
  let files: string[];
  try {
    files = (await fs.readdir(path.join(dataDir(), slug))).filter((f) => f.endsWith('.json'));
  } catch {
    return undefined;
  }
  for (const file of files.sort().reverse().slice(0, MAX_NAME_LOOKUPS)) {
    const conv = await getConversation(slug, file.slice(0, -'.json'.length));
    if (conv?.project.name) return conv.project.name;
  }
  return undefined;
}

/** Folder under `projectsRoot()` whose collision-aware slug is `slug` — one
 * non-recursive `readdir` (`projectSiblingNames`) and the same slug rule as
 * `scanProjects`, without its per-project git/package probing. */
async function projectFolderName(slug: string): Promise<string | undefined> {
  const candidates = (await projectSiblingNames()).map((name) => ({ name, slug: slugify(name) }));
  disambiguateSlugCollisions(candidates);
  return candidates.find((c) => c.slug === slug)?.name;
}

/**
 * The `project` to fill for `slug`. `name`: the label the hub already shows
 * for this slug (a conversation already filed under it), else the matching project folder name,
 * else the slug itself. No `path`: a local absolute path must not be minted
 * for a body that never asked for it — `convo_create` is on the remote MCP
 * surface, whose `convo_read` projection only redacts `origin`
 * (server/mcp/hubReadTools.ts).
 */
export async function resolveDraftProject(slug: string): Promise<DraftProject> {
  const name =
    (await latestConversationName(slug)) ?? (await projectFolderName(slug)) ?? slug;
  return { slug, name };
}

/**
 * Fills the defaults above IN PLACE on `draft` (same mutation idiom as the
 * `obj.x ??= …` lines it replaces). Returns an error message when the draft
 * must be refused, `null` otherwise. `resolveProject` is only called when
 * `project` is absent or incomplete.
 */
export async function applyConversationDraftDefaults(
  draft: unknown,
  slug: string,
  opts: { now: string; resolveProject?: (slug: string) => Promise<DraftProject> },
): Promise<string | null> {
  if (!isPlainObject(draft)) {
    return 'le corps de la conversation doit être un objet JSON ({ id, title, items, … })';
  }
  const given = draft.project;
  if (isPlainObject(given) && given.slug != null && given.slug !== slug) {
    return (
      `project.slug « ${String(given.slug)} » ≠ slug du chemin « ${slug} » — ` +
      `retire "project" du JSON (il est rempli depuis le slug du chemin) ou aligne les deux`
    );
  }

  draft.schemaVersion ??= 1;
  draft.status ??= 'pending';
  draft.createdAt ??= opts.now;
  draft.updatedAt ??= opts.now;

  // A non-object `project` (string, number…) is left for the schema to reject.
  if (given == null || (isPlainObject(given) && (given.slug == null || given.name == null))) {
    const resolved = await (opts.resolveProject ?? resolveDraftProject)(slug);
    draft.project = isPlainObject(given)
      ? { ...resolved, ...given, slug, name: given.name ?? resolved.name }
      : resolved;
  }

  if (Array.isArray(draft.items)) {
    for (const item of draft.items) {
      if (!isPlainObject(item)) continue;
      item.status ??= 'pending';
      if (item.prompt == null && typeof item.title === 'string' && item.title) {
        item.prompt = item.title;
      }
    }
  }
  return null;
}

/**
 * Hub WRITE tools — Lot 1 du chantier « MCP distant / connecteur claude.ai ».
 *
 * Trois nouveaux outils d'ÉCRITURE métier, enregistrés sur le MÊME bus MCP que
 * les outils « cerveau » (`brainTools.ts`), via le MÊME chokepoint
 * (`BrainToolRegistrar.register` — validation zod E/S, contrôle d'accès,
 * rate-limit, timeout, sanitisation, audit append-only). Gardés dans un
 * fichier séparé pour ne pas alourdir `brainTools.ts` (déjà ~978 lignes).
 *
 * Chaque outil ici est un MIROIR d'un chemin d'écriture agent EXISTANT — il ne
 * réinvente ni logique ni schéma :
 *   - `chip_create`   miroir de `createChipFromInput` (chipStore.ts), le même
 *     service que le CLI `bun run chips add` et le hook spawn_task.
 *   - `convo_create`  miroir de `capture_gate` (brainTools.ts) / `convo create`
 *     (server/cli/convo.ts) — même garde d'identité, même store — PLUS une
 *     garde DÉDIÉE (secret_request toujours refusé) que ni l'un ni l'autre
 *     n'impose.
 *   - `remind_add`    miroir de `remind add` (server/cli/remind.ts), via les
 *     helpers PARTAGÉS `loadOrInitRemindersConversation`/`newReminderItemId`
 *     (server/services/reminderStore.ts) — PLUS un retry borné sur conflit de
 *     verrou optimiste (le CLI n'a jamais eu ce besoin : un seul appelant
 *     local à la fois ; un outil MCP distant peut être appelé concurremment).
 */
import { promises as fs } from 'node:fs';
import path from 'node:path';
import { z } from 'zod';
import type { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';

import { BrainToolRegistrar } from './middleware';
import { projectsRoot, root, dataDir } from '../config';
import { isSafeSegment } from '../services/slug';
import { createChipFromInput } from '../services/chipStore';
import { resolveProjectRootFromCwd } from '../services/projectRoot';
import {
  ConversationSchema,
  type Conversation,
} from '../../src/types/conversation';
import {
  getConversation,
  saveConversation,
  saveFailureReason,
} from '../services/conversationStore';
import { checkConversationWrite } from '../services/identityGuard';
import { applyConversationDraftDefaults } from '../services/conversationDraft';
import {
  REMINDERS_SLUG,
  REMINDERS_ID,
  loadOrInitRemindersConversation,
  buildReminderItem,
} from '../services/reminderStore';
import { resolveAgentOrigin, readGitBranch, createdByFromOrigin } from '../lib/agentOrigin';
import type { AgentOrigin } from '../../src/types/agentOrigin';

/* -------------------------------------------------------------------------- */
/*  chip_create                                                                */
/* -------------------------------------------------------------------------- */

const chipCreateResultSchema = z.object({
  created: z.boolean(),
  deduped: z.boolean(),
  id: z.string(),
  slug: z.string(),
  path: z.string(),
});

/**
 * Resolve the `cwd` a chip should be filed under from an OPTIONAL `project`
 * slug: `<PROJECTS_ROOT>/<project>` when that directory genuinely exists on
 * disk, else the workstation repo root itself (`root()`) — same fallback for
 * both "unknown slug" and "no slug given" (P1 in the chantier brief).
 * `createChipFromInput` (chipStore.ts) then derives the REAL project
 * slug/name from this `cwd` exactly as the CLI/hooks do — this function only
 * decides which directory to hand it.
 */
async function resolveChipCwd(project: string | undefined): Promise<string> {
  if (!project) return root();
  if (!isSafeSegment(project)) {
    throw new Error(`project invalide « ${project} » — segment non sûr`);
  }
  const candidate = path.join(projectsRoot(), project);
  try {
    const st = await fs.stat(candidate);
    if (st.isDirectory()) return candidate;
  } catch {
    // fall through to the workstation root fallback below.
  }
  return root();
}

/* -------------------------------------------------------------------------- */
/*  convo_create                                                              */
/* -------------------------------------------------------------------------- */

const convoCreateResultSchema = z.object({
  created: z.boolean(),
  slug: z.string(),
  id: z.string(),
  title: z.string(),
  status: z.string(),
  itemCount: z.number(),
  path: z.string(),
  origin: z.string(),
});

/**
 * IN-PROCESS serialization of `convo_create`'s read-then-create against ONE
 * `(slug, id)` key — same create-time race as `remind_add` above (two
 * concurrent calls can both observe "no file yet" and neither ever conflicts
 * on `saveConversation`'s optimistic lock), but scoped PER KEY rather than a
 * single global queue: unlike `remind_add` (which always writes the SAME
 * evergreen `_reminders` conversation, so a global queue costs nothing),
 * `convo_create` calls on different `(slug, id)` pairs share no resource and
 * must stay concurrent — a global queue here would serialize unrelated
 * conversation creations for no reason.
 */
const convoCreateQueues = new Map<string, Promise<unknown>>();

function serializeConvoCreate<T>(key: string, fn: () => Promise<T>): Promise<T> {
  const prev = convoCreateQueues.get(key) ?? Promise.resolve();
  const run = prev.then(fn, fn);
  convoCreateQueues.set(
    key,
    run.then(
      () => undefined,
      () => undefined,
    ),
  );
  return run;
}

/* -------------------------------------------------------------------------- */
/*  remind_add                                                                */
/* -------------------------------------------------------------------------- */

const remindAddResultSchema = z.object({
  created: z.boolean(),
  itemId: z.string(),
  text: z.string(),
  dueAt: z.string().optional(),
  path: z.string(),
  origin: z.string(),
});

/** Bounded retry cap on an optimistic-lock conflict (409) — see file header. */
const REMIND_ADD_MAX_ATTEMPTS = 3;

/**
 * IN-PROCESS serialization of `remind_add`'s read-modify-write against the
 * evergreen `_reminders` conversation. `saveConversation`'s optimistic lock
 * (`existing.updatedAt !== incoming.updatedAt`) only fires when a PRIOR file
 * already exists — on the very FIRST reminder ever written, two concurrent
 * callers can both observe "no file yet" (`existing === null` on BOTH sides
 * of the check, inside `saveConversation` itself) and neither write ever
 * conflicts with the other: whichever `atomicWrite` lands last simply
 * overwrites the other's brand-new file, silently dropping the first item —
 * a true create-time race no `updatedAt` comparison (nor a bounded retry
 * keyed off it) can catch, since no conflict is ever reported to retry on.
 *
 * A single MCP server process (this file) CAN close that gap deterministically
 * for calls it itself receives, by never letting two `remind_add` executions
 * interleave their read-modify-write in the first place — a simple promise
 * chain achieves that without touching the shared store's locking semantics
 * (which stays exactly as-is, still the correct defense for a genuine
 * CROSS-process conflict, e.g. this server and the `remind add` CLI writing
 * at the same moment — kept as the retry loop below).
 */
let remindAddQueue: Promise<unknown> = Promise.resolve();

function serializeRemindAdd<T>(fn: () => Promise<T>): Promise<T> {
  const run = remindAddQueue.then(fn, fn);
  // Never let a rejection wedge the queue for subsequent callers.
  remindAddQueue = run.then(
    () => undefined,
    () => undefined,
  );
  return run;
}

