export interface RegisterHubWriteToolsOptions {
  /**
   * An existing registrar to register onto, instead of a fresh one — lets a
   * future caller (e.g. an HTTP transport wanting one shared rate-limiter /
   * audit surface across the brain tools AND these hub-write tools) share
   * state across requests. Defaults to a fresh `BrainToolRegistrar`, exactly
   * like `registerBrainTools`.
   */
  registrar?: BrainToolRegistrar;
  /**
   * When set, only tool names in this set are registered — lets a future
   * caller (e.g. a filtered remote surface) expose a subset of these three
   * tools. Defaults to registering all of them.
   */
  allow?: ReadonlySet<string>;
  /**
   * D2 (chantier « provenance de session », lot 2 — widened to ALL THREE
   * write tools by the P1 fix below): forces the ORIGIN of every record
   * `chip_create`/`convo_create`/`remind_add` create through THIS mount,
   * taking full priority over per-request env detection AND any `origin` the
   * caller's own payload might carry. Used by the remote HTTP surface
   * (`remoteSurface.ts`) to stamp every chip/conversation/reminder created
   * via claude.ai mobile with `runtime: 'claude-ai'` — the Claude Code
   * session env vars (if any) visible to THIS process belong to the SERVER,
   * never to the remote caller, so trusting them here would misattribute
   * authorship. Passed as `explicit` to `resolveAgentOrigin`: wins outright
   * when it carries BOTH `runtime` and `sessionId` (I2), otherwise only
   * nudges `runtime`/`capturedBy` (I6c) — see `server/lib/agentOrigin.ts`.
   *
   * INVARIANT (P1 fix, revue adversariale): `originOverride` used to be wired
   * into `convo_create` ONLY — `chip_create` and `remind_add`, despite being
   * on the SAME `REMOTE_TOOL_NAMES` whitelist, silently fell through to their
   * own default env-based resolution, which reads the SERVER process's env
   * (misattributing to whatever local Claude Code session happens to be
   * running the workstation server, or to `runtime:'unknown'` under
   * launchd). Every write-tool handler below now threads `opts?.originOverride`
   * through — if you add a FOURTH hub-write tool, wire it here too, and copy
   * this comment to its handler so the next one can't be missed either.
   */
  originOverride?: Partial<AgentOrigin>;
}

/**
 * Register `chip_create`, `convo_create`, `remind_add` on `server` through the
 * shared middleware. Returns the registrar so the caller can read
 * `registered` (the tool-list fingerprint), exactly like `registerBrainTools`.
 */
export function registerHubWriteTools(
  server: McpServer,
  opts?: RegisterHubWriteToolsOptions,
): BrainToolRegistrar {
  const reg = opts?.registrar ?? new BrainToolRegistrar();
  const allow = opts?.allow;
  const wants = (name: string) => !allow || allow.has(name);

  /* ---- chip_create (WRITE) ---- */
  if (wants('chip_create')) {
    reg.register(server, {
      name: 'chip_create',
      description:
        'Crée un task chip persistant (miroir de `bun run chips add` / spawn_task) sous un projet optionnel (slug sous PROJECTS_ROOT ; racine workstation par défaut ou si le slug est inconnu). Fusionne (dédup) dans un chip open/launched existant de même titre.',
      access: 'write',
      inputSchema: {
        title: z.string().min(1).describe('Titre court (déduplication par slug de ce titre)'),
        prompt: z.string().min(1).describe('Prompt complet, source de vérité pour l’exécution'),
        tldr: z.string().optional().describe('Résumé 1-2 phrases'),
        project: z
          .string()
          .optional()
          .describe('Slug de projet sous PROJECTS_ROOT ; racine workstation si absent/inconnu'),
      },
      outputSchema: chipCreateResultSchema,
      handler: async (args) => {
        const cwd = await resolveChipCwd(args.project);
        // INVARIANT (P1 fix, chantier « provenance de session », revue
        // adversariale) — see `RegisterHubWriteToolsOptions.originOverride`'s
        // doc for the full rationale: every hub-write tool MUST apply
        // `opts?.originOverride` before its origin is resolved, or a record
        // created through the remote mount misattributes authorship to
        // whichever session happens to be running THIS server process. Only
        // resolve an explicit origin here when an override is actually
        // set — otherwise leave `origin` undefined so `createChipFromInput`
        // keeps its own default resolution (identical `resolveAgentOrigin`
        // call, but against the NORMALIZED `cwd` it derives internally).
        const origin = opts?.originOverride
          ? resolveAgentOrigin({
              env: process.env,
              cwd: resolveProjectRootFromCwd(cwd),
              source: 'mcp',
              explicit: opts.originOverride,
              git: readGitBranch,
            })
          : undefined;
        const { chip, deduped } = await createChipFromInput({
          title: args.title,
          prompt: args.prompt,
          tldr: args.tldr,
          cwd,
          source: 'mcp',
          origin,
        });
        return {
          created: !deduped,
          deduped,
          id: chip.id,
          slug: chip.project.slug,
          path: `data/chips/${chip.project.slug}/${chip.id}.json`,
        };
      },
    });
  }

  /* ---- convo_create (WRITE) ---- */
  if (wants('convo_create')) {
    reg.register(server, {
      name: 'convo_create',
      description:
        'Crée une conversation du hub de décisions (miroir de `convo create` / `capture_gate`) — JAMAIS de réponse pré-remplie (garde d’identité), et JAMAIS d’item kind:"secret_request" (garde dédiée — un secret ne transite que par le Coffre, jamais par cet outil distant).',
      access: 'write',
      inputSchema: {
        slug: z.string().min(1).describe('Slug projet (dossier data/conversations/<slug>/)'),
        id: z.string().min(1).describe('Id de la conversation (nom de fichier)'),
        conversation: z
          .record(z.string(), z.unknown())
          .describe(
            'Corps de conversation validé par ConversationSchema (src/types/conversation.ts) — items SANS response. Champs serveur (schemaVersion/status/createdAt/updatedAt/createdBy, project depuis `slug`, status/prompt des items) auto-remplis si absents ; un project.slug ≠ `slug` est refusé.',
          ),
      },
      outputSchema: convoCreateResultSchema,
      handler: async (args) => {
        if (!isSafeSegment(args.slug)) {
          throw new Error(`slug projet invalide « ${args.slug} »`);
        }
        if (!isSafeSegment(args.id)) {
          throw new Error(`id de conversation invalide « ${args.id} »`);
        }

        const raw: Record<string, unknown> = { ...(args.conversation as Record<string, unknown>) };
        const rawItems = Array.isArray(raw.items) ? (raw.items as unknown[]) : [];

        // DEDICATED GUARD (convo_create only, checked BEFORE anything else):
        // refuse ANY item kind:"secret_request" outright, response or not.
        // `checkConversationWrite` below does NOT catch a freshly-authored
        // secret_request item with no `response` yet — it only flags items
        // that already carry a response — so this tool-specific rule closes
        // that gap: a secret VALUE must only ever be delivered via le Coffre
        // (the dashboard's own secret_request flow), never through this
        // remote write tool.
        const secretRequestIds = rawItems
          .filter(
            (it): it is Record<string, unknown> =>
              it !== null && typeof it === 'object' && (it as Record<string, unknown>).kind === 'secret_request',
          )
          .map((it, i) => (typeof it.id === 'string' && it.id ? it.id : `#${i}`));
        if (secretRequestIds.length > 0) {
          throw new Error(
            `convo_create refuse tout item kind:"secret_request" (${secretRequestIds.join(', ')}) — ` +
              'un secret ne doit jamais transiter par cet outil distant ; utilise le Coffre depuis le dashboard.',
          );
        }

        // Fill server-managed fields, exactly like `convo create` / `capture_gate`
        // (server/services/conversationDraft.ts — `project` included).
        const now = new Date().toISOString();
        raw.id ??= args.id;
        const draftError = await applyConversationDraftDefaults(raw, args.slug, { now });
        if (draftError) throw new Error(draftError);

        // INVARIANT (P1 fix, chantier « provenance de session », revue
        // adversariale) — see `RegisterHubWriteToolsOptions.originOverride`'s
        // doc for the full rationale: every hub-write tool MUST apply
        // `opts?.originOverride` before its origin is resolved, or a record
        // created through the remote mount misattributes authorship to
        // whichever session happens to be running THIS server process.
        //
        // D2/D3 (chantier « provenance de session », lot 2): derive a real
        // AgentOrigin instead of a naked `createdBy` default (was 'claude').
        // ALWAYS re-resolves (never `??=`-skips even when the caller already
        // sent an `origin`) so a malformed/partial caller origin is never
        // persisted as-is. `createdByFromOrigin` then derives the legacy
        // `createdBy` enum FROM whichever origin won.
        //
        // P2 fix (constat 1a, revue adversariale): the ONLY trusted
        // `explicit` input is `opts?.originOverride` — a mount-level value
        // this SERVER's own code sets (the remote surface pins
        // `runtime:'claude-ai'`), never derived from request data. An
        // earlier version also fed the CALLER's own `conversation.origin`
        // (shape-checked against `AgentOriginSchema.partial()`, but its
        // VALUES are entirely the caller's to pick) into `explicit` —
        // `resolveAgentOrigin`'s branch 1 stamps ANY `explicit.runtime` +
        // `explicit.sessionId` pair `capturedBy:'explicit'` unconditionally,
        // so a local `convo_create` call carrying
        // `conversation.origin: {runtime:'claude', sessionId:'<anything>'}`
        // came back at the MAXIMUM rank — trivial, permanent session-identity
        // forgery (no repair path outranks 'explicit'). `capturedBy` "is
        // meaningless coming FROM a caller, it is this resolver's own
        // verdict" (`server/lib/agentOrigin.ts`) — a caller-supplied origin
        // is therefore never passed to `explicit` at all; a genuine LOCAL
        // agent call still resolves correctly through the env-based branches
        // below (this MCP mount is spawned in-process, so `process.env`
        // carries the REAL caller's session vars when there is no mount
        // override).
        raw.origin = resolveAgentOrigin({
          env: process.env,
          cwd: root(),
          source: 'mcp',
          explicit: opts?.originOverride,
          git: readGitBranch,
        });
        raw.createdBy = createdByFromOrigin(raw.origin as AgentOrigin, undefined);

        if (raw.id !== args.id) {
          throw new Error(`conversation.id « ${String(raw.id)} » ≠ id demandé « ${args.id} »`);
        }

        // IDENTITY GUARD (security-critical) — actor is the agent/MCP path.
        // Rejects any item carrying a response (or a forged answeredAt).
        const guard = checkConversationWrite(raw, 'claude');
        if (!guard.allowed) throw new Error(guard.reason);

        const parsed = ConversationSchema.safeParse(raw);
        if (!parsed.success) {
          throw new Error(`schéma invalide: ${JSON.stringify(parsed.error.format())}`);
        }
        // No post-parse `project.slug` check: applyConversationDraftDefaults refuses a
        // differing slug, and saveConversation re-checks it against `args.slug`.

        return serializeConvoCreate(`${args.slug}/${args.id}`, async () => {
          const existing = await getConversation(args.slug, args.id);
          if (existing) {
            throw new Error(
              `la conversation « ${args.id} » existe déjà sous « ${args.slug} » (elle peut contenir des réponses). Refus d’écraser via MCP.`,
            );
          }

          const result = await saveConversation(args.slug, args.id, raw);
          if (!result.ok) {
            throw new Error(`store a rejeté l’écriture: ${saveFailureReason(result)}`);
          }
          const w = result.conversation;
          // CREATE-TIME RACE GUARD: `saveConversation`'s optimistic lock only
          // fires when a PRIOR file already existed with a different
          // `updatedAt` — on the very FIRST write, two concurrent callers can
          // both observe `existing === null` and both proceed; whichever
          // `atomicWrite` lands last wins, and the loser's own post-write
          // re-read (what `saveConversation` returns as `result.conversation`)
          // can come back showing the WINNER's content instead of its own.
          // `serializeConvoCreate` above already prevents two IN-PROCESS calls
          // on the SAME key from ever interleaving — this check is
          // defense-in-depth for a genuine CROSS-process race (e.g. the
          // `convo create` CLI writing the same id at the same moment). A
          // create conflict means a DIFFERENT conversation now legitimately
          // owns this id — fail explicitly rather than retry (retrying would
          // just overwrite that other, real conversation).
          if (w.createdAt !== raw.createdAt || w.items.length !== rawItems.length) {
            throw new Error(
              `convo_create: course détectée sur « ${args.id} » sous « ${args.slug} » — un autre écrivain a créé cette conversation au même instant ; réessaie avec un autre id.`,
            );
          }
          return {
            created: true,
            slug: args.slug,
            id: w.id,
            title: w.title,
            status: w.status,
            itemCount: w.items.length,
            // ABSOLUTE path (lot 3's external hook derives dataRoot() from it).
            path: path.join(dataDir(), args.slug, `${w.id}.json`),
            origin: `${w.origin?.runtime ?? 'unknown'} ${w.origin?.sessionId ?? '-'} (${w.origin?.capturedBy ?? 'none'})`,
          };
        });
      },
    });
  }

  /* ---- remind_add (WRITE) ---- */
  if (wants('remind_add')) {
    reg.register(server, {
      name: 'remind_add',
      description:
        'Ajoute un rappel dans la conversation évergreen `_reminders` du hub (miroir de `bun run remind add`) — visible en tête du dashboard. Retry borné (3 tentatives) sur conflit de verrou optimiste, pour un appel distant potentiellement concurrent.',
      access: 'write',
      inputSchema: {
        text: z.string().min(1).describe('Texte du rappel'),
        due: z.string().optional().describe('Échéance, date ISO'),
        project: z.string().optional().describe('Slug/nom affiché du projet d’origine (contexte, pas de résolution disque)'),
      },
      outputSchema: remindAddResultSchema,
      handler: async (args) => {
        if (args.due !== undefined && Number.isNaN(Date.parse(args.due))) {
          throw new Error(`due n'est pas une date ISO valide : "${args.due}"`);
        }

        return serializeRemindAdd(async () => {
          let lastConflictReason: string | undefined;
          for (let attempt = 1; attempt <= REMIND_ADD_MAX_ATTEMPTS; attempt++) {
            const conversation = await loadOrInitRemindersConversation('mcp');
            const isNew =
              conversation.items.length === 0 && conversation.updatedAt === conversation.createdAt;

            // INVARIANT (P1 fix, chantier « provenance de session », revue
            // adversariale) — see `RegisterHubWriteToolsOptions.originOverride`'s
            // doc for the full rationale: every hub-write tool MUST apply
            // `opts?.originOverride` before its origin is resolved, or a
            // record created through the remote mount misattributes
            // authorship to whichever session happens to be running THIS
            // server process. `remind_add` used to be one of the two tools
            // that silently skipped this — fixed here.
            const origin = resolveAgentOrigin({
              env: process.env,
              cwd: process.cwd(),
              source: 'mcp',
              explicit: opts?.originOverride,
              git: readGitBranch,
            });
            const item = buildReminderItem(
              { text: args.text, dueAt: args.due, project: args.project },
              origin,
            );

            const nextConversation: Conversation = {
              ...conversation,
              items: [...conversation.items, item],
            };

            // Same discipline as `remind add`: the guard is scoped to ONLY the
            // new item, never the evergreen conversation's full history (which
            // may already carry human-answered reminders).
            const guard = checkConversationWrite({ items: [item] }, 'claude');
            if (!guard.allowed) throw new Error(guard.reason);

            const result = await saveConversation(REMINDERS_SLUG, REMINDERS_ID, nextConversation);
            if (result.ok) {
              // `saveConversation` re-reads the file AFTER writing and returns
              // THAT (see conversationStore.ts, "Re-read to return exactly what
              // was persisted") — but `existing`'s optimistic-lock check inside
              // `saveConversation` only fires when a PRIOR file already existed
              // with a DIFFERENT updatedAt. On the very FIRST reminder ever
              // written, two concurrent callers can both observe "no file yet"
              // (both `existing === null`) and both proceed to write with no
              // conflict detected at all — whichever atomicWrite's rename lands
              // LAST wins, and the loser's own post-write re-read can come back
              // showing the WINNER's content (their item silently dropped,
              // despite `result.ok === true`). This self-check closes that gap:
              // verify OUR item genuinely survived onto the persisted copy
              // before trusting `ok`; if it didn't, treat it exactly like an
              // optimistic-lock conflict and retry — the next attempt's fresh
              // `loadOrInitRemindersConversation()` read will see the other
              // writer's item already there and append onto it correctly.
              // (In practice, `serializeRemindAdd` above already prevents two
              // IN-PROCESS calls from ever reaching this point interleaved —
              // this check is defense-in-depth for a cross-process race, e.g.
              // the `remind add` CLI writing at the same moment.)
              if (result.conversation.items.some((it) => it.id === item.id)) {
                return {
                  created: isNew,
                  itemId: item.id,
                  text: item.prompt,
                  dueAt: item.dueAt,
                  // ABSOLUTE path (mirrors `convo_create`'s own result field, and
                  // is what a hook's `deriveDataRoot` needs to find — lot 3/6).
                  path: path.join(dataDir(), REMINDERS_SLUG, `${REMINDERS_ID}.json`),
                  origin: `${item.origin?.runtime ?? 'unknown'} ${item.origin?.sessionId ?? '-'} (${item.origin?.capturedBy ?? 'none'})`,
                };
              }
              lastConflictReason = 'item non retrouvé après écriture (course sur la création initiale)';
              continue;
            }
            if ('conflict' in result && result.conflict) {
              // Optimistic-lock conflict (409-equivalent): another writer saved
              // the evergreen conversation between our read and our write.
              // Re-read fresh and reapply the SAME delta (a brand-new item, so
              // there is nothing to reconcile — just append again onto the now-
              // current on-disk copy) rather than losing this reminder.
              lastConflictReason = saveFailureReason(result);
              continue;
            }
            throw new Error(`store a rejeté l’écriture: ${saveFailureReason(result)}`);
          }
          throw new Error(
            `remind_add: échec après ${REMIND_ADD_MAX_ATTEMPTS} tentatives (conflit de verrou optimiste persistant) — ${lastConflictReason ?? 'raison inconnue'}`,
          );
        });
      },
    });
  }

  return reg;
}

