/* ---- capture_gate (WRITE — create a gate, NEVER a response) ---- */
if (wants('capture_gate')) {
reg.register(server, {
  name: 'capture_gate',
  description:
    'Crée une conversation de décision (approval/question) dans le hub — JAMAIS de réponse. Le garde d’identité rejette toute tentative d’écrire response.decision. Miroir exact de `convo create`.',
  access: 'write',
  inputSchema: {
    slug: z.string().min(1).describe('Slug projet (dossier)'),
    conversation: z
      .record(z.string(), z.unknown())
      .describe('Corps de conversation (items SANS response). Champs serveur auto-remplis, project compris (depuis `slug`).'),
  },
  outputSchema: gateCreateResultSchema,
  handler: async (args) => {
    if (!isSafeSegment(args.slug)) {
      throw new Error(`slug projet invalide « ${args.slug} »`);
    }
    // Fill server-managed fields, exactly like `convo create`
    // (server/services/conversationDraft.ts — `project` included).
    const now = new Date().toISOString();
    const obj = { ...(args.conversation as Record<string, unknown>) };
    const draftError = await applyConversationDraftDefaults(obj, args.slug, { now });
    if (draftError) throw new Error(draftError);
    // D2/D3 (chantier « provenance de session », lot 2): derive a real
    // AgentOrigin instead of a naked `createdBy` default (was 'claude') — same
    // pattern as `convo create` (server/cli/convo.ts). ALWAYS re-resolved,
    // never `??=`: a caller-supplied `conversation.origin` (e.g.
    // `capturedBy:'explicit'` + any sessionId) was persisted verbatim — a
    // permanent session-identity forgery, closed the same way as the MCP twin
    // `convo_create` (server/mcp/hubWriteTools.ts, constat 1a).
    obj.origin = resolveAgentOrigin({
      env: process.env,
      cwd: root(),
      source: 'mcp',
      git: readGitBranch,
    });
    obj.createdBy = createdByFromOrigin(obj.origin as AgentOrigin, undefined);

    // IDENTITY GUARD (security-critical) — actor is the agent/MCP path.
    const guard = checkConversationWrite(obj, 'claude');
    if (!guard.allowed) throw new Error(guard.reason);

    const parsed = ConversationSchema.safeParse(obj);
    if (!parsed.success) {
      throw new Error(`schéma invalide: ${JSON.stringify(parsed.error.format())}`);
    }
    // No post-parse `project.slug` check: applyConversationDraftDefaults refuses a
    // differing slug, and saveConversation re-checks it against `args.slug`.
    const id = parsed.data.id;
    const existing = await getConversation(args.slug, id);
    if (existing) {
      throw new Error(
        `la conversation « ${id} » existe déjà (elle peut contenir des réponses). Refus d’écraser via MCP.`,
      );
    }

    const result = await saveConversation(args.slug, id, obj);
    if (!result.ok) {
      throw new Error(`store a rejeté l’écriture: ${saveFailureReason(result)}`);
    }
    const w = result.conversation;
    return {
      created: true,
      slug: args.slug,
      id: w.id,
      title: w.title,
      status: w.status,
      itemCount: w.items.length,
      path: `data/conversations/${args.slug}/${w.id}.json`,
      note: 'Porte créée. Dis à l’utilisateur d’ouvrir la conversation et de répondre.',
    };
  },
});
}

