import { z } from 'zod';

import { AgentOriginSchema, AgentRuntimeSchema, CaptureLayerSchema, NestedIdsSchema } from './agentOrigin';

/**
 * Shared data contract for the "workstation" app — the SINGLE SOURCE OF TRUTH
 * for the Conversation/Decision Hub and the project Dashboard.
 *
 * Defines zod schemas (runtime validation) and derives the TypeScript types
 * from them via z.infer.
 *
 *  - The front imports it relatively (e.g. "../types/conversation").
 *  - The server imports it relatively (e.g. "../../src/types/conversation")
 *    and MUST validate incoming JSON with ConversationSchema before persisting.
 *
 * Nine item kinds cover the ways the user converses with Claude:
 *   decision       — pick from options (single / multi / custom)
 *   question       — open free-text answer
 *   approval       — go / no-go / request changes
 *   checklist      — tick a set of items
 *   proposal       — Claude proposes content; user accepts / revises / rejects
 *   note           — read-only context / support (optionally acknowledge)
 *   rating         — a value on a scale (severity, priority, confidence…)
 *   secret_request — deliver a secret value OUT of the chat (le Coffre)
 *   reminder       — a short note to self, marked done when handled
 */

/* -------------------------------------------------------------------------- */
/*  Reduced origin (list/summary shapes — not the full AgentOrigin)           */
/* -------------------------------------------------------------------------- */

/**
 * Reduced projection of `AgentOriginSchema` for list/summary shapes
 * (`ConversationMeta`, `InboxItem`, and — chantier provenance-session, lot 8 —
 * `ChipMeta` in `src/types/chip.ts`) that are read far more often than the
 * full record — only the fields those views actually render. Deliberately
 * NOT the full `AgentOriginSchema` (no cwd/repoRoot/branch/etc.); kept as its
 * own small object here (rather than re-derived per call site) so every use
 * site shares the exact same shape instead of silently drifting. Exported so
 * `chip.ts` reuses it rather than re-declaring a fourth copy.
 *
 * `nestedIds` (revue adversariale du 2026-09-08, constat P2) — SANS lui,
 * `buildSessionLinks` (`server/services/agentSessions/links.ts`) ne peut
 * matcher une conversation/un chip sur les ids imbriqués d'un Codex lancé
 * DEPUIS une session Claude (ou l'inverse) : la page « Sessions » de la
 * session parente montrait alors les documents Galley et les rappels de la
 * session imbriquée, mais jamais ses conversations ni ses chips — résultat
 * partiel, silencieux. `candidateKeys` (`links.ts`) lit déjà `nestedIds` sur
 * n'importe quel objet qui en porte un ; il ne restait qu'à l'ajouter ICI et
 * à le propager (`conversationStore.toMeta`, `chipStore.toReducedOrigin`).
 */
export const ReducedOriginSchema = z.object({
  runtime: AgentRuntimeSchema,
  sessionId: z.string().optional(),
  capturedBy: CaptureLayerSchema,
  nestedIds: NestedIdsSchema.optional(),
});

/* -------------------------------------------------------------------------- */
/*  Status enums                                                              */
/* -------------------------------------------------------------------------- */

export const ConversationStatusSchema = z.enum([
  'pending',
  'in_progress',
  'completed',
  'archived',
]);

export const ItemStatusSchema = z.enum(['pending', 'answered', 'skipped']);
export const ItemPrioritySchema = z.enum(['low', 'normal', 'high', 'urgent']);
export const AgentFollowupStatusSchema = z.enum(['none', 'pending', 'handled']);

export const ITEM_KINDS = [
  'decision',
  'question',
  'approval',
  'checklist',
  'proposal',
  'note',
  'rating',
  'secret_request',
  'reminder',
] as const;

/* -------------------------------------------------------------------------- */
/*  Choices / options                                                         */
/* -------------------------------------------------------------------------- */

export const OptionSchema = z.object({
  id: z.string().min(1),
  label: z.string().min(1),
  description: z.string().optional(),
  recommended: z.boolean().optional(),
});

export const AttachmentSchema = z.object({
  id: z.string().min(1),
  label: z.string().min(1),
  href: z.string().min(1),
  kind: z.enum(['file', 'image', 'url']).optional(),
});

/* -------------------------------------------------------------------------- */
/*  Item base                                                                 */
/* -------------------------------------------------------------------------- */

/**
 * Fields shared by every item kind. Kept as a raw shape object so each item
 * schema can spread it before adding its own discriminant + payload (the
 * discriminator must live directly on each branch of a discriminatedUnion).
 *
 * `title` is a short label used for the table of contents / navigation; when
 * absent the UI falls back to a truncated `prompt`.
 */
const itemBaseShape = {
  id: z.string().min(1),
  title: z.string().optional(),
  prompt: z.string().min(1),
  context: z.string().optional(),
  priority: ItemPrioritySchema.optional(),
  dueAt: z.string().datetime().optional(),
  blockedReason: z.string().optional(),
  status: ItemStatusSchema.default('pending'),
  comment: z.string().optional(),
  answeredAt: z.string().datetime().optional(),
};

/* ---- decision ------------------------------------------------------------ */

export const DecisionResponseSchema = z.object({
  selectedOptionIds: z.array(z.string()),
  customText: z.string().optional(),
  /**
   * Provenance marker: this response was written by the second-brain bridge
   * mirroring a decision resolved outside the hub (never typed by a human in
   * the dashboard). Write-authority enforcement lives in identityGuard.ts,
   * not here — this schema only accepts the shape.
   */
  mirroredFromApprovalId: z.string().optional(),
});

export const DecisionItemSchema = z.object({
  ...itemBaseShape,
  kind: z.literal('decision'),
  options: z.array(OptionSchema).min(1),
  allowMultiple: z.boolean().optional(),
  allowCustom: z.boolean().optional(),
  response: DecisionResponseSchema.optional(),
});

/* ---- question ------------------------------------------------------------ */

export const QuestionResponseSchema = z.object({
  text: z.string(),
});

