/**
 * Règles transversales du type secret_request, appliquées au POINT UNIQUE de
 * validation (ConversationValidationSchema, utilisé par saveConversation/
 * saveTemplate en WP3) — SANS toucher à ConversationSchema lui-même, pour ne
 * casser aucun usage structurel (.shape / .extend) existant.
 *   1. env_file exige targetPath ; les autres modes l'interdisent.
 *   2. env_file interdit les champs multiline (PEM → drop_file/keychain, P1).
 *   3. ttlHours / burnAfterRead réservés à drop_file.
 *   4. field.id et field.name uniques dans l'item.
 */
export function refineSecretRequestItem(
  item: SecretRequestItem,
  ctx: z.RefinementCtx,
  itemIndex: number,
): void {
  const at = (...path: (string | number)[]) => ['items', itemIndex, ...path];
  const mode = item.delivery.mode;
  // 1. targetPath ↔ mode
  if (mode === 'env_file' && !item.delivery.targetPath) {
    ctx.addIssue({ code: z.ZodIssueCode.custom, path: at('delivery', 'targetPath'),
      message: 'targetPath est requis pour le mode env_file.' });
  }
  if (mode !== 'env_file' && item.delivery.targetPath !== undefined) {
    ctx.addIssue({ code: z.ZodIssueCode.custom, path: at('delivery', 'targetPath'),
      message: 'targetPath est réservé au mode env_file.' });
  }
  // 2. multiline interdit en env_file (P1)
  if (mode === 'env_file') {
    item.fields.forEach((f, i) => {
      if (f.multiline) {
        ctx.addIssue({ code: z.ZodIssueCode.custom, path: at('fields', i, 'multiline'),
          message: 'Un champ multiline (PEM) ne peut pas être livré en env_file — utiliser drop_file ou keychain.' });
      }
    });
  }
  // 3. ttlHours / burnAfterRead réservés à drop_file
  if (mode !== 'drop_file') {
    if (item.delivery.ttlHours !== undefined) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, path: at('delivery', 'ttlHours'),
        message: 'ttlHours est réservé au mode drop_file.' });
    }
    if (item.delivery.burnAfterRead !== undefined) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, path: at('delivery', 'burnAfterRead'),
        message: 'burnAfterRead est réservé au mode drop_file.' });
    }
  }
  // 4. unicité field.id et field.name
  const seenIds = new Set<string>();
  const seenNames = new Set<string>();
  item.fields.forEach((f, i) => {
    if (seenIds.has(f.id)) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, path: at('fields', i, 'id'),
        message: `field.id dupliqué : ${f.id}` });
    }
    seenIds.add(f.id);
    if (seenNames.has(f.name)) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, path: at('fields', i, 'name'),
        message: `field.name dupliqué : ${f.name}` });
    }
    seenNames.add(f.name);
  });
}

/**
 * ConversationSchema + règles transversales secret_request. À utiliser au point
 * de validation serveur (saveConversation/saveTemplate en WP3). ConversationSchema
 * lui-même reste un z.object non-refiné pour préserver .shape / .extend.
 */
export const ConversationValidationSchema = ConversationSchema.superRefine((conv, ctx) => {
  conv.items.forEach((item, index) => {
    if (item.kind === 'secret_request') {
      refineSecretRequestItem(item, ctx, index);
    }
  });
});

