/* -------------------------------------------------------------------------- */
/*  Completion rules                                                          */
/* -------------------------------------------------------------------------- */

/**
 * Whether an item must be answered for the conversation to be "completed".
 *  - 'skipped' items never count.
 *  - a `note` without `requiresAck` is purely informational and never blocks.
 */
export function itemCountsTowardCompletion(item: Item): boolean {
  if (item.status === 'skipped') return false;
  if (item.kind === 'note' && !item.requiresAck) return false;
  return true;
}

/**
 * Recompute the overall conversation status from its items.
 *
 *  - 'completed'   : there is at least one counting item and ALL counting
 *                    items are 'answered'.
 *  - 'in_progress' : at least one item is 'answered' (but not all).
 *  - 'pending'     : otherwise.
 *
 * 'archived' is a manual/terminal state, never produced here.
 */
export function computeStatus(items: Item[]): ConversationStatus {
  const counting = items.filter(itemCountsTowardCompletion);
  const answered = counting.filter((item) => item.status === 'answered');

  if (counting.length > 0 && answered.length === counting.length) {
    return 'completed';
  }
  if (items.some((item) => item.status === 'answered')) {
    return 'in_progress';
  }
  return 'pending';
}

/**
 * SINGLE SOURCE OF TRUTH for "does this conversation still need human
 * attention" (dashboard open counts, project tiles, the "open" tab filter).
 * A conversation closed by the second-brain bridge's raccord A
 * (bridge/watch.ExternalResolve.ts, RA-AC-18 — an approval resolved outside
 * the hub, e.g. the app) never gets its items answered: the identity guard
 * (server/services/identityGuard.ts) forbids the agent path from ever writing
 * an item `response`, so `status` stays 'pending' forever even though nothing
 * is actually awaiting the user. `agentFollowupStatus === 'handled'` is the
 * one closing signal that write path IS allowed to set — treat it as
 * equivalent to completion here rather than in the write path.
 */
export function isConversationOpen(
  m: Pick<ConversationMeta, 'status' | 'agentFollowupStatus'>
): boolean {
  return m.status !== 'completed' && m.status !== 'archived' && m.agentFollowupStatus !== 'handled';
}

/**
 * The `ConversationStatus` to DISPLAY (StatusPill, badges) — distinct from
 * the raw persisted `status`. A conversation closed via the bridge's raccord
 * A keeps `status: 'pending'`/`'in_progress'` forever (see isConversationOpen
 * above): showing that raw status would badge an already-resolved
 * conversation as still needing the user's attention.
 */
export function effectiveConversationStatus(
  m: Pick<ConversationMeta, 'status' | 'agentFollowupStatus'>
): ConversationStatus {
  if (!isConversationOpen(m) && (m.status === 'pending' || m.status === 'in_progress')) {
    return 'completed';
  }
  return m.status;
}

/**
 * Items still awaiting a human, in a conversation isConversationOpen agrees
 * is genuinely open — the combined predicate every "à traiter" count (inbox,
 * bell, push, activity, project health) needs. Centralized so a future call
 * site can't reintroduce the bug of counting a pending item without also
 * checking the conversation-level closing signal.
 */
export function openPendingItems(conversation: Conversation): Item[] {
  if (!isConversationOpen(conversation)) return [];
  return conversation.items.filter(
    (item) => item.status === 'pending' && itemCountsTowardCompletion(item)
  );
}

