  const rawItems = Array.isArray(rawObj.items) ? (rawObj.items as unknown[]) : [];
  return error.issues
    .map((issue) => {
      const [root, idx, ...rest] = issue.path;
      if (root === 'items' && typeof idx === 'number') {
        const { id, kind } = describeRawItem(rawItems[idx], `#${idx}`);
        return formatItemIssue(id, kind, rest, issue);
