 * rewrote it) — we REFUSE the write and return the current copy so a stale
 * client can never silently clobber good answers. The client should reload.
 */
export async function saveConversation(
  slug: string,
  id: string,
  body: unknown,
  opts: SaveOptions = {},
): Promise<SaveResult> {
  // Validate with the SECRET-AWARE schema: ConversationSchema + the cross-cutting
  // secret_request rules (targetPath↔mode, multiline↔env_file, ttl/burn↔drop_file,
  // unique field id/name). ConversationSchema itself stays un-refined for callers
  // that rely on .shape / .extend.
  const parsed = ConversationValidationSchema.safeParse(body);
  if (!parsed.success) {
    return { ok: false, error: parsed.error.format() };
  }

  const incoming = parsed.data;

  // The file is stored at conversationPath(slug, id) derived from the URL.
  // Reject a body whose id/slug disagree with the path it is stored under, so
  // the persisted record can never be self-inconsistent (id/slug in the file
  // always match the location on disk and the URL any client used to PUT it).
  if (incoming.id !== id || incoming.project.slug !== slug) {
    return {
      ok: false,
      error: 'id/slug in body must match URL',
    };
  }

  // Secret guardrail — refuse a high-confidence credential value anywhere in the
  // hub (scans the raw body so a smuggled value in an unknown key is caught too).
  const blocked = secretScanBlock(body, opts);
  if (blocked) {
    return { ok: false, secretBlocked: true, patterns: blocked };
  }

  const filePath = conversationPath(slug, id);

  // Optimistic-lock check against the current on-disk version.
  const existing = await readConversationFile(filePath);
  if (existing && existing.updatedAt !== incoming.updatedAt) {
    return {
      ok: false,
      conflict: true,
      current: existing,
      error:
        'Le fichier a été modifié depuis son ouverture. Rechargez la page pour récupérer la dernière version — vos réponses enregistrées ne sont pas écrasées.',
    };

  return process.env.NODE_ENV === 'production' ? 'prod' : 'dev';
}

/**
 * Where conversation JSON files live. Derived from `dataRoot()` so a dev
 * instance (WORKSTATION_DATA_ROOT set) is isolated from prod. Every read/write
 * path of the conversation store and its readers (store, insights, activity,
 * project scanner, history, watcher, the `convo` CLI, the project-conversations
 * route) MUST call this instead of the frozen `DATA_DIR` const. Default is
 * identical to the const when neither env var is set — prod behavior unchanged.
 */
export function dataDir(): string {
  return path.join(dataRoot(), 'conversations');
}

/** Persistent mirror of Claude Code Desktop task chips. */
export const CHIPS_DIR = path.join(ROOT, 'data', 'chips');

/**
 * Same as `CHIPS_DIR` but resolved from `WORKSTATION_ROOT` at CALL TIME (same
 * frozen-const isolation hazard as `dataDir()`): the chip store's read/write
 * paths call this so a chip test that redirects `WORKSTATION_ROOT` in
 * `beforeAll` never writes into the REAL `data/chips/`, regardless of which test
 * file imported `config` first. Prod behavior unchanged (default when unset).
 */
export function chipsDir(): string {
  return path.join(dataRoot(), 'chips');
}

/**
 * Local registry of "External Tasks" (launchd daemons/jobs the dashboard
 * observes + drives via launchctl — see server/services/taskManager.ts).
 * Resolved from `WORKSTATION_ROOT` at CALL TIME (same frozen-const isolation
 * hazard as `chipsDir()`): a test that redirects `WORKSTATION_ROOT` in
 * `beforeAll` must never write into the REAL `data/tasks/`. Prod behavior
 * unchanged (default when unset).
 */
export function tasksDir(): string {
  return path.join(dataRoot(), 'tasks');
}

