insightsRouter.post('/conversations/:slug/:id/export', async (req, res) => {
  const { slug, id } = req.params;
  if (!isSafeSegment(slug) || !isSafeSegment(id)) {
    res.status(400).json({ error: 'Invalid slug or id' });
    return;
  }

  try {
    const conversation = await getConversation(slug, id);
    if (!conversation) {
      res.status(404).json({ error: 'Conversation not found' });
      return;
    }
    const projectPath = conversation.project.path;
    if (!projectPath) {
      res.status(400).json({ error: 'Project path missing from conversation' });
      return;
    }
    const exportDir = path.join(projectPath, 'docs', 'conversations');
    await fs.mkdir(exportDir, { recursive: true });
    const filePath = path.join(exportDir, `${id}.md`);
    await fs.writeFile(filePath, renderConversationMarkdown(conversation), 'utf8');
    res.json({ success: true, filePath });
  } catch (err) {
    res.status(500).json({ error: 'Failed to write conversation export', detail: String(err) });
  }
});

